INSERT INTO `career_jobs` (`id`, `job_title`, `job_description`, `responsibilities`, `qualifications`, `position`, `location`, `experience`, `status`, `created_at`, `updated_at`) VALUES
(1, 'IR Head', '<ul>\r\n<li>Develop and implement comprehensive investor relations strategies to effectively communicate the company&rsquo;s financial performance, and growth prospects to investors, analysts, and other stakeholders.</li>\r\n<li>Serve as the primary point of contact for investors and analysts, addressing inquiries, providing timely updates, and managing relationships to enhance investor confidence and trust in the company.</li>\r\n<li>Lead the planning and execution of investor events, including earnings calls, investor conferences, roadshows, and investor meetings, to effectively communicate the company&rsquo;s story and thesis.</li>\r\n<li>Collaborate closely with senior management, finance, legal, and other teams to ensure alignment on key messages, financial disclosures, and regulatory compliance requirements.</li>\r\n<li>Monitor market trends, competitor activities, and investor sentiment to identify opportunities and risks, providing strategic insights and recommendations to management.</li>\r\n<li>Oversee the preparation and distribution of investor communications materials, including press releases, presentations, annual reports, and other financial disclosures, ensuring accuracy, consistency, and compliance with regulatory standards.</li>\r\n<li>Drive fundraising efforts through QIPs and secondary market offerings, managing the end-to-end process from preparation and documentation to execution and post-offering activities.</li>\r\n<li>Coordinate with external advisors, investment banks, legal counsel, and other stakeholders to facilitate fundraising transactions and optimize capital structure decisions.</li>\r\n<li>Maintain a comprehensive understanding of the company&rsquo;s business operations, financial performance, industry dynamics, and regulatory environment to effectively address investor inquiries and provide strategic guidance.</li>\r\n<li>Stay informed of best practices, industry benchmarks, and regulatory developments related to investor relations and fundraising, continuously seeking opportunities to enhance the effectiveness and efficiency of our investor relations function.</li>\r\n</ul>\r\n<p><strong>Qualifications</strong></p>\r\n<ul>\r\n<li>Bachelor&rsquo;s degree in finance/business/ economics, or related field; MBA or CFA preferred.</li>\r\n<li>Minimum of 12-15 years of experience in investor relations, corporate finance, investment banking, or related fields, preferably within the real estate industry.</li>\r\n<li>Proven track record in fundraising through Qualified Institutional Placements (QIPs) and secondary market offerings, with a deep understanding of capital markets and investor preferences.</li>\r\n<li>Strong financial acumen, analytical skills, and ability to interpret financial statements, valuation methodologies, and complex financial data.</li>\r\n<li>Excellent communication and interpersonal skills, with the ability to articulate complex concepts in a clear and concise manner to diverse audiences.</li>\r\n<li>Strategic mindset, with the ability to think critically, anticipate investor needs, and develop innovative solutions to address challenges and opportunities.</li>\r\n<li>Results-oriented approach, with a focus on driving performance, delivering results, and exceeding expectations in a fast-paced, dynamic environment.</li>\r\n<li>Strong project management skills, with the ability to prioritize tasks, manage multiple deadlines, and work effectively under pressure to meet business objectives.</li>\r\n<li>Demonstrated leadership abilities, with experience managing teams, fostering a collaborative culture, and building relationships across departments and functions.</li>\r\n<li>High level of integrity, professionalism, and ethical conduct, with a commitment to transparency, accountability, and compliance with regulatory standards.</li>\r\n</ul>', '', '', 'Manager', 'Mumbai', '12+ years', 1, '2026-09-30 06:16:13', '2026-10-07 13:20:53'),
(3, 'Engineer', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Requirements\\n&bull; Qualified CA having 7 to 9 Years of exps., having fair knowledge of accounting processes to identify the tax issues.\\n&bull; Attention to detail with strong analytical skills.\\n&bull; Good communication skills.\\n \\nKRAs:\\n&bull; Manage the Direct &amp; Indirect tax compliances, assessments, litigation, appeared before the Tax Authorities, and managed various audit issues.\\n&bull; Handling Advance Tax payments, Tax returns, reports, and necessary paperwork for the company.\\n&bull; Ensure complete tax compliances for DT &amp; IDT (Mainly GST).\\n&bull; GST ITC recon, Reversal of Non-eligible ITC etc.\\n&bull; Co-ordinating with the Tax counsel for tax advisory and opinion. Preparing the facts for Case for opinion\\n&bull; Provide assistance to both external and internal stakeholder.\\n&bull; Ensure periodic review of financial from tax perspective.\\n&bull; Maintaining solid ties with clients through engaging with them on a frequent basis.\\n&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:13309,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\"><strong>Project Supervision &amp; Execution :</strong></span></p>\r\n<ul>\r\n<li>Ensure supervision of all construction work at site and execution of project as per the schedule and specification.</li>\r\n<li>Ensure real time monitoring and completion of work within the contract period to avoid cost escalations and cascading financial implications.</li>\r\n<li>Responsible for timely completion of following all works related to construction.</li>\r\n<li>Timely information to project manager for requirement of construction material and equipment required to avoid any delay in project because of material unavailability.</li>\r\n<li>Immediate inform project manager in case of any abnormality, accident or issue at site to project manager to ensure such matter doesn&rsquo;t affect construction activities.</li>\r\n</ul>\r\n<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Requirements\\n&bull; Qualified CA having 7 to 9 Years of exps., having fair knowledge of accounting processes to identify the tax issues.\\n&bull; Attention to detail with strong analytical skills.\\n&bull; Good communication skills.\\n \\nKRAs:\\n&bull; Manage the Direct &amp; Indirect tax compliances, assessments, litigation, appeared before the Tax Authorities, and managed various audit issues.\\n&bull; Handling Advance Tax payments, Tax returns, reports, and necessary paperwork for the company.\\n&bull; Ensure complete tax compliances for DT &amp; IDT (Mainly GST).\\n&bull; GST ITC recon, Reversal of Non-eligible ITC etc.\\n&bull; Co-ordinating with the Tax counsel for tax advisory and opinion. Preparing the facts for Case for opinion\\n&bull; Provide assistance to both external and internal stakeholder.\\n&bull; Ensure periodic review of financial from tax perspective.\\n&bull; Maintaining solid ties with clients through engaging with them on a frequent basis.\\n&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:13309,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\"><strong>Labour Management :</strong></span></p>\r\n<ul>\r\n<li>Responsible for assessing the labour requirement as per the need of the work and ensure adequate deployment of labour.</li>\r\n<li>Liaison with labour contractors and ensure that the work doesn&rsquo;t suffer because of inadequate supply of labour or there is no excess labour supply anywhere.</li>\r\n<li>Keep a track of labour supply and ensure no mismanagement of labour.</li>\r\n</ul>\r\n<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Requirements\\n&bull; Qualified CA having 7 to 9 Years of exps., having fair knowledge of accounting processes to identify the tax issues.\\n&bull; Attention to detail with strong analytical skills.\\n&bull; Good communication skills.\\n \\nKRAs:\\n&bull; Manage the Direct &amp; Indirect tax compliances, assessments, litigation, appeared before the Tax Authorities, and managed various audit issues.\\n&bull; Handling Advance Tax payments, Tax returns, reports, and necessary paperwork for the company.\\n&bull; Ensure complete tax compliances for DT &amp; IDT (Mainly GST).\\n&bull; GST ITC recon, Reversal of Non-eligible ITC etc.\\n&bull; Co-ordinating with the Tax counsel for tax advisory and opinion. Preparing the facts for Case for opinion\\n&bull; Provide assistance to both external and internal stakeholder.\\n&bull; Ensure periodic review of financial from tax perspective.\\n&bull; Maintaining solid ties with clients through engaging with them on a frequent basis.\\n&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:13309,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\"><strong>MIS:</strong></span></p>\r\n<ul>\r\n<li>Ensure proper record maintenance of all documents related to project.</li>\r\n<li>Ensure timely submission of reports asked by seniors as and when required.</li>\r\n</ul>\r\n<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Requirements\\n&bull; Qualified CA having 7 to 9 Years of exps., having fair knowledge of accounting processes to identify the tax issues.\\n&bull; Attention to detail with strong analytical skills.\\n&bull; Good communication skills.\\n \\nKRAs:\\n&bull; Manage the Direct &amp; Indirect tax compliances, assessments, litigation, appeared before the Tax Authorities, and managed various audit issues.\\n&bull; Handling Advance Tax payments, Tax returns, reports, and necessary paperwork for the company.\\n&bull; Ensure complete tax compliances for DT &amp; IDT (Mainly GST).\\n&bull; GST ITC recon, Reversal of Non-eligible ITC etc.\\n&bull; Co-ordinating with the Tax counsel for tax advisory and opinion. Preparing the facts for Case for opinion\\n&bull; Provide assistance to both external and internal stakeholder.\\n&bull; Ensure periodic review of financial from tax perspective.\\n&bull; Maintaining solid ties with clients through engaging with them on a frequent basis.\\n&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:13309,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\"><strong>Self Development:</strong></span></p>\r\n<ul>\r\n<li>Attend all training programs (behavioral/ technical), seminars conducted/sponsored by company.</li>\r\n<li>Initiate self learning and gain knowledge of other skills.</li>\r\n</ul>', '', '', 'Sr. Engineer', 'Mumbai', '8+ years', 1, '2026-10-07 13:22:56', '2026-10-07 13:22:56'),
(4, 'Document Controller', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;The Document Controller is responsible for managing, organizing, and maintaining all project documentation and records. This role ensures that documents are accurate, up-to-date, and easily accessible for project stakeholders and compliance purposes. The Document Controller also plays a key role in coordinating between various departments and ensuring that documentation processes align with company standards and industry regulations. &quot;}\" data-sheets-userformat=\"{&quot;2&quot;:13181,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\">The Document Controller is responsible for managing, organizing, and maintaining all project documentation and records. This role ensures that documents are accurate, up-to-date, and easily accessible for project stakeholders and compliance purposes. The Document Controller also plays a key role in coordinating between various departments and ensuring that documentation processes align with company standards and industry regulations.</span></p>', '', '', 'Senior Executive', 'Mumbai', '3+ years', 1, '2026-10-07 13:23:33', '2026-10-07 13:23:33'),
(5, 'Sales Closing Manager', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;The Sales Closing Manager is responsible for overseeing the finalization of real estate transactions, ensuring a smooth and efficient closing process. This role involves coordinating with various stakeholders, managing paperwork, and addressing any issues that arise to ensure that sales deals are completed successfully. The Sales Closing Manager plays a crucial role in converting potential sales into finalized transactions and enhancing customer satisfaction.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:13181,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\">The Sales Closing Manager is responsible for overseeing the finalization of real estate transactions, ensuring a smooth and efficient closing process. This role involves coordinating with various stakeholders, managing paperwork, and addressing any issues that arise to ensure that sales deals are completed successfully. The Sales Closing Manager plays a crucial role in converting potential sales into finalized transactions and enhancing customer satisfaction.</span></p>', '', '', 'Assistant Manager', 'Mumbai', '5-7 years', 1, '2026-10-07 13:23:53', '2026-10-07 13:23:53'),
(6, 'Account Executive', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;The Accounts Executive is responsible for managing and maintaining financial records, preparing financial reports, and ensuring accurate and timely processing of transactions within the real estate industry. This role involves handling day-to-day accounting tasks, supporting financial operations, and ensuring compliance with accounting standards and company policies.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:13181,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\">The Accounts Executive is responsible for managing and maintaining financial records, preparing financial reports, and ensuring accurate and timely processing of transactions within the real estate industry. This role involves handling day-to-day accounting tasks, supporting financial operations, and ensuring compliance with accounting standards and company policies.</span></p>', '', '', 'Executive', 'Kalyan', '10+ years', 1, '2026-10-07 13:24:16', '2026-10-07 13:24:16'),
(7, 'Marketing Executive', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;The Offline Marketing Executive in the real estate industry is responsible for planning and executing offline marketing strategies and campaigns to promote properties, attract potential clients, and enhance brand visibility. This role involves managing various traditional marketing activities, including events, print media, and direct marketing initiatives to drive sales and achieve marketing goals. &quot;}\" data-sheets-userformat=\"{&quot;2&quot;:13181,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\">The Offline Marketing Executive in the real estate industry is responsible for planning and executing offline marketing strategies and campaigns to promote properties, attract potential clients, and enhance brand visibility. This role involves managing various traditional marketing activities, including events, print media, and direct marketing initiatives to drive sales and achieve marketing goals.</span></p>', '', '', 'Executive', 'Kalyan', '2-3 years', 1, '2026-10-07 13:24:36', '2026-10-07 13:24:36'),
(8, 'CRM MIS', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;The CRM MIS Executive in the real estate industry is responsible for managing and analyzing customer relationship management (CRM) data, generating management information system (MIS) reports, and supporting the CRM team with data-driven insights. This role involves maintaining CRM systems, producing detailed reports on customer interactions and sales performance, and ensuring that CRM data is accurate and up-to-date to support strategic decision-making. &quot;}\" data-sheets-userformat=\"{&quot;2&quot;:13181,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\">The CRM MIS Executive in the real estate industry is responsible for managing and analyzing customer relationship management (CRM) data, generating management information system (MIS) reports, and supporting the CRM team with data-driven insights. This role involves maintaining CRM systems, producing detailed reports on customer interactions and sales performance, and ensuring that CRM data is accurate and up-to-date to support strategic decision-making.</span></p>', '', '', 'Executive', 'Mumbai', '2-3 years', 1, '2026-10-07 13:24:54', '2026-10-07 13:24:54'),
(9, 'MEP', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;The MEP Engineer in the real estate industry is responsible for designing, implementing, and managing the mechanical, electrical, and plumbing systems of real estate projects. This role involves ensuring that MEP systems are integrated effectively within the architectural design, meet regulatory standards, and are completed on time and within budget. The MEP Engineer collaborates closely with other engineering disciplines, contractors, and stakeholders to ensure the successful delivery of building projects. &quot;}\" data-sheets-userformat=\"{&quot;2&quot;:13181,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\">The MEP Engineer in the real estate industry is responsible for designing, implementing, and managing the mechanical, electrical, and plumbing systems of real estate projects. This role involves ensuring that MEP systems are integrated effectively within the architectural design, meet regulatory standards, and are completed on time and within budget. The MEP Engineer collaborates closely with other engineering disciplines, contractors, and stakeholders to ensure the successful delivery of building projects.</span></p>', '', '', 'Assistant Manager', 'Mumbai', '5-7 years', 1, '2026-10-07 13:25:12', '2026-10-07 13:25:12'),
(10, 'Senior Engineer', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;The Senior Engineer &ndash; Projects in the real estate industry is responsible for overseeing and managing the engineering aspects of construction projects from inception to completion. This role involves coordinating with various stakeholders, ensuring project specifications are met, and delivering projects on time and within budget. The Senior Engineer is expected to lead engineering teams, address technical issues, and ensure adherence to safety and quality standards.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:13181,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\">The Senior Engineer &ndash; Projects in the real estate industry is responsible for overseeing and managing the engineering aspects of construction projects from inception to completion. This role involves coordinating with various stakeholders, ensuring project specifications are met, and delivering projects on time and within budget. The Senior Engineer is expected to lead engineering teams, address technical issues, and ensure adherence to safety and quality standards.</span></p>', '', '', 'Senior Executive', 'Mumbai', '5-7 years', 1, '2026-10-07 13:25:31', '2026-10-07 13:25:31'),
(11, 'Quality Supervisor', '<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Requirements\\n&bull; Qualified CA having 7 to 9 Years of exps., having fair knowledge of accounting processes to identify the tax issues.\\n&bull; Attention to detail with strong analytical skills.\\n&bull; Good communication skills.\\n \\nKRAs:\\n&bull; Manage the Direct &amp; Indirect tax compliances, assessments, litigation, appeared before the Tax Authorities, and managed various audit issues.\\n&bull; Handling Advance Tax payments, Tax returns, reports, and necessary paperwork for the company.\\n&bull; Ensure complete tax compliances for DT &amp; IDT (Mainly GST).\\n&bull; GST ITC recon, Reversal of Non-eligible ITC etc.\\n&bull; Co-ordinating with the Tax counsel for tax advisory and opinion. Preparing the facts for Case for opinion\\n&bull; Provide assistance to both external and internal stakeholder.\\n&bull; Ensure periodic review of financial from tax perspective.\\n&bull; Maintaining solid ties with clients through engaging with them on a frequent basis.\\n&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:13309,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\"><strong>Quality Control:</strong></span></p>\r\n<ul>\r\n<li>Responsible for physical verification of quality standards of material used such as Brick, sand, aggregate, fly ash bricks and ensure they are of right quality</li>\r\n<li>Ensure all the constructions are made as per international concrete standards</li>\r\n<li>Regular review of the safety practices followed at sites/offices and ensure that adequate safety measures have been taken</li>\r\n</ul>\r\n<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Requirements\\n&bull; Qualified CA having 7 to 9 Years of exps., having fair knowledge of accounting processes to identify the tax issues.\\n&bull; Attention to detail with strong analytical skills.\\n&bull; Good communication skills.\\n \\nKRAs:\\n&bull; Manage the Direct &amp; Indirect tax compliances, assessments, litigation, appeared before the Tax Authorities, and managed various audit issues.\\n&bull; Handling Advance Tax payments, Tax returns, reports, and necessary paperwork for the company.\\n&bull; Ensure complete tax compliances for DT &amp; IDT (Mainly GST).\\n&bull; GST ITC recon, Reversal of Non-eligible ITC etc.\\n&bull; Co-ordinating with the Tax counsel for tax advisory and opinion. Preparing the facts for Case for opinion\\n&bull; Provide assistance to both external and internal stakeholder.\\n&bull; Ensure periodic review of financial from tax perspective.\\n&bull; Maintaining solid ties with clients through engaging with them on a frequent basis.\\n&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:13309,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\"><strong>Process &amp; Policies:</strong></span></p>\r\n<ul>\r\n<li>To quality process set and work continuously to improve the same</li>\r\n<li>Responsible for creating quality awareness amongst all through proper communication</li>\r\n<li>Prepare a checklist of test/documents required for various testing and ensure adherence to same</li>\r\n</ul>\r\n<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Requirements\\n&bull; Qualified CA having 7 to 9 Years of exps., having fair knowledge of accounting processes to identify the tax issues.\\n&bull; Attention to detail with strong analytical skills.\\n&bull; Good communication skills.\\n \\nKRAs:\\n&bull; Manage the Direct &amp; Indirect tax compliances, assessments, litigation, appeared before the Tax Authorities, and managed various audit issues.\\n&bull; Handling Advance Tax payments, Tax returns, reports, and necessary paperwork for the company.\\n&bull; Ensure complete tax compliances for DT &amp; IDT (Mainly GST).\\n&bull; GST ITC recon, Reversal of Non-eligible ITC etc.\\n&bull; Co-ordinating with the Tax counsel for tax advisory and opinion. Preparing the facts for Case for opinion\\n&bull; Provide assistance to both external and internal stakeholder.\\n&bull; Ensure periodic review of financial from tax perspective.\\n&bull; Maintaining solid ties with clients through engaging with them on a frequent basis.\\n&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:13309,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\"><strong>Statutory Compliance:</strong></span></p>\r\n<ul>\r\n<li>Ensure all guidelines related to pollution control are met and there is no penalty</li>\r\n<li>Ensure that there is no penalty, compliance issue for using low quality of building material or faulty construction technique</li>\r\n<li>Ensure that all documentation, record, compliance are maintained properly to avoid any penalty</li>\r\n<li>Ensure that there is no claim for any damage caused by low quality raw material, process, parameter, etc.</li>\r\n</ul>\r\n<p><span data-sheets-root=\"1\" data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;Requirements\\n&bull; Qualified CA having 7 to 9 Years of exps., having fair knowledge of accounting processes to identify the tax issues.\\n&bull; Attention to detail with strong analytical skills.\\n&bull; Good communication skills.\\n \\nKRAs:\\n&bull; Manage the Direct &amp; Indirect tax compliances, assessments, litigation, appeared before the Tax Authorities, and managed various audit issues.\\n&bull; Handling Advance Tax payments, Tax returns, reports, and necessary paperwork for the company.\\n&bull; Ensure complete tax compliances for DT &amp; IDT (Mainly GST).\\n&bull; GST ITC recon, Reversal of Non-eligible ITC etc.\\n&bull; Co-ordinating with the Tax counsel for tax advisory and opinion. Preparing the facts for Case for opinion\\n&bull; Provide assistance to both external and internal stakeholder.\\n&bull; Ensure periodic review of financial from tax perspective.\\n&bull; Maintaining solid ties with clients through engaging with them on a frequent basis.\\n&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:13309,&quot;3&quot;:{&quot;1&quot;:0},&quot;5&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;6&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;7&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;8&quot;:{&quot;1&quot;:[{&quot;1&quot;:2,&quot;2&quot;:0,&quot;5&quot;:{&quot;1&quot;:2,&quot;2&quot;:0}},{&quot;1&quot;:0,&quot;2&quot;:0,&quot;3&quot;:3},{&quot;1&quot;:1,&quot;2&quot;:0,&quot;4&quot;:1}]},&quot;9&quot;:0,&quot;10&quot;:1,&quot;11&quot;:4,&quot;12&quot;:0,&quot;15&quot;:&quot;Calibri&quot;,&quot;16&quot;:11}\"><strong>Certification:</strong></span></p>\r\n<ul>\r\n<li>Work towards achieving ISO and other international quality parameter certificates</li>\r\n<li>Ensure regular audit and proper compliance for regular renewal of such certificates</li>\r\n<li>Computer proficiency</li>\r\n<li>Knowledge of real estate industry</li>\r\n</ul>', '', '', 'Quality Supervisor', 'Mumbai', '4-5 years', 1, '2026-10-07 13:25:51', '2026-10-07 13:25:51');

